import { defineConfig } from 'oxlint'
import core from 'ultracite/oxlint/core'
import next from 'ultracite/oxlint/next'
import react from 'ultracite/oxlint/react'
import vitest from 'ultracite/oxlint/vitest'

export default defineConfig({
  extends: [core, react, next, vitest],
  // Registers the @shadcn/lint plugin; the shadcn/* rules are enabled in `rules`.
  jsPlugins: ['@shadcn/lint'],
  ignorePatterns: [
    ...core.ignorePatterns,
    // Drizzle introspection output is regenerated by `pnpm db:pull`; linting it
    // only produces findings that any regeneration would undo.
    'src/lib/db/drizzle/**',
    '.shipstudio/**',
    // One-off CLI scripts; ESLint already ignores them.
    'scripts/**',
    // Playwright specs; ESLint already ignores them, and the vitest preset only
    // produces vitest-style noise (globals, import style) against Playwright APIs.
    'src/e2e/**',
    // `.sanity/runtime/*` is regenerated by `sanity dev` and any edit is
    // discarded. ESLint already ignores it.
    '.sanity/**',
  ],
  rules: {
    // Opinionated *style* rules with no autofixer. oxfmt owns formatting, so these
    // can't be auto-resolved and only generate file-by-file noise that fights the
    // established conventions across this (pre-existing) codebase. Correctness rules
    // (eqeqeq, no-shadow, no-use-before-define, require-await, etc.) stay ON.

    // Forces alphabetical object keys — fights the conventional Sanity schema
    // ordering (name → title → type → …) used throughout this codebase.
    'sort-keys': 'off',
    // Function declaration vs. expression is a style preference; the codebase uses
    // `function` declarations throughout and there is no autofixer.
    'func-style': 'off',
    // Concise vs. block arrow bodies — pure style, no autofixer.
    'arrow-body-style': 'off',
    // Nested ternaries are used intentionally for compact JSX/value selection.
    'no-nested-ternary': 'off',
    'unicorn/no-nested-ternary': 'off',
    // Negated conditions are fine and often clearer here.
    'no-negated-condition': 'off',
    'unicorn/no-negated-condition': 'off',
    // Inline comments, unnamed capture groups, digit grouping, destructuring and
    // function scoping are all stylistic preferences with no autofixer.
    'no-inline-comments': 'off',
    'prefer-named-capture-group': 'off',
    'unicorn/numeric-separators-style': 'off',
    'prefer-destructuring': 'off',
    'unicorn/consistent-function-scoping': 'off',
    // Array iteration style; forEach/reduce are used intentionally.
    'unicorn/no-array-for-each': 'off',
    'unicorn/no-array-reduce': 'off',
    // Bitwise operators are used intentionally in color/hash math (e.g. OG images).
    'no-bitwise': 'off',
    // High-noise, low-value pedantry with no autofixer that the codebase doesn't
    // follow. Not bug-catching for this app — kept off to stop file-by-file churn.
    'require-unicode-regexp': 'off', // `u` flag on ASCII regexes
    'require-await': 'off', // async route handlers without await
    'no-await-in-loop': 'off', // sequential awaits are intentional in scripts
    'no-alert': 'off', // confirm()/alert() used in admin tooling
    'no-empty-function': 'off',
    'no-useless-return': 'off',
    'promise/prefer-await-to-then': 'off',
    'unicorn/filename-case': 'off', // mixed file-naming conventions already in place
    'unicorn/prefer-array-find': 'off',
    // Function declarations are hoisted and used before their definition
    // throughout (helpers at the bottom of a module). Classes and variables are
    // still checked because using those early is a real TDZ bug.
    'no-use-before-define': ['error', { functions: false, classes: true, variables: true }],
    // More style-only rules with no autofixer, same policy as above.
    complexity: 'off', // cyclomatic-complexity budget; no autofixer, pure judgement
    'jsdoc/require-returns-description': 'off', // JSDoc prose completeness
    'jsdoc/require-param-description': 'off', // JSDoc prose completeness
    'promise/prefer-await-to-callbacks': 'off', // Node callback APIs (fs, child_process) are fine
    'promise/avoid-new': 'off', // `new Promise` is the idiom for wrapping callbacks/timers
    'import/no-named-as-default': 'off', // naming a default import after a named export
    'import/no-named-as-default-member': 'off', // `default.member` access on a module
    'unicorn/import-style': 'off', // `import path from 'node:path'` vs named imports
    'unicorn/text-encoding-identifier-case': 'off', // 'utf-8' vs 'utf8' spelling
    'no-plusplus': 'off', // `i++` in classic loops
    // React: stable-reference default props and shadcn-style inline subcomponents
    // (e.g. ui/calendar) are accepted patterns here.
    'react/no-object-type-as-default-prop': 'off',
    'react/no-unstable-nested-components': 'off',

    // @shadcn/lint design-system rules. All at `warn` while the backlog is
    // measured (see DESIGN.md). `shadcn/no-unknown-classes` is intentionally NOT
    // enabled: the codebase uses custom non-Tailwind classes (btn, btn--md,
    // text-size-90, ...) that it would flag on every use.
    'shadcn/no-restyle': [
      'warn',
      {
        allow: ['layout'],
        contracts: [
          { pattern: '^CardTitle$', allow: ['layout', 'typography'], deny: ['font-*'] },
          {
            pattern: '^Card$|(Content|Header|Footer|Group|Panel)$',
            allow: ['layout', 'spacing'],
            deny: ['p-0', 'px-0'],
          },
          { pattern: '^Avatar$', allow: ['size-*'] },
          {
            pattern: '^Button$',
            // `allow: ['layout']` (not an explicit list) because this codebase puts
            // plain placement classes (flex-1, ml-auto, size-8) on Buttons.
            allow: ['layout'],
            deny: ['w-*'],
            message: {
              spacing: 'Use a Button size: {{sizes|none defined}}.',
              default: 'Use a Button variant: {{variants|none defined}}.',
            },
          },
        ],
      },
    ],
    'shadcn/no-raw-colors': 'warn',
    'shadcn/no-arbitrary-values': ['warn', { allow: ['layout'] }],
    'shadcn/no-inline-styles': 'warn',
    'shadcn/require-static-classes': 'warn',
  },
  settings: { shadcn: { note: 'See DESIGN.md for design rules and approved exceptions.' } },
  overrides: [
    {
      // Vendored shadcn/ui primitives — generated code we don't hand-maintain, so
      // relax the few rules its patterns trip (shadowing, param reassign, ==, etc.).
      files: ['src/components/ui/**'],
      rules: {
        'no-shadow': 'off',
        'no-param-reassign': 'off',
        eqeqeq: 'off',
        'no-eq-null': 'off',
        'unicorn/no-document-cookie': 'off',
        // The primitives define the design system, so restyle/arbitrary/static
        // checks don't apply to them. no-raw-colors and no-inline-styles stay on.
        'shadcn/no-restyle': 'off',
        'shadcn/no-arbitrary-values': 'off',
        'shadcn/require-static-classes': 'off',
      },
    },
  ],
})
